import base64,pathlib
R=pathlib.Path(__file__).resolve().parent.parent/'v3'
def b64(n): return 'data:image/jpeg;base64,'+base64.b64encode((R/'img'/n).read_bytes()).decode()
fonts=(R/'fonts/home.css').read_text()
jobs=[('Bathroom','bath'),('Exterior repaint','home'),('Cabinet refinish','kitchen'),('Front door stain','door'),('Garage doors','gdoor')]
cards=''.join(f'<button class="card" type="button" aria-pressed="false" aria-label="{t}. Tap to switch between the finished job and before"><img class="a" src="{b64(k+"-after-sm.jpg")}" alt="{t} finished by JB\'S Pro Painters"><img class="b" src="{b64(k+"-before-sm.jpg")}" alt="{t} before painting"><span class="tag"><b>Fresh coat</b>{t}</span><span class="hint">Tap for before</span></button>' for t,k in jobs)
drip='<svg class="drip" viewBox="0 0 1200 90" preserveAspectRatio="none" aria-hidden="true"><path fill="#eef2fa" d="M0 90V30c40 0 60-10 90-10s40 22 70 22 30-30 70-30 40 26 80 26 40-20 80-20 40 30 80 30 40-24 90-24 40 18 80 18 40-28 90-28 40 22 80 22 40-18 80-18 40 24 70 24 50-10 70-10H1200V90z"/><g fill="#0b3fae"><path d="M95 0h14v34c0 9-14 9-14 0z"/><path d="M330 0h12v52c0 8-12 8-12 0z"/><path d="M640 0h14v44c0 9-14 9-14 0z"/><path d="M930 0h12v58c0 8-12 8-12 0z"/></g></svg>'
html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>JB'S Pro Painters LLC | Painters in Gilbert, Mesa and the East Valley, AZ</title>
<meta name="description" content="Owner-operated interior and exterior painters serving Gilbert, Mesa, Chandler, Tempe, Scottsdale and Queen Creek, AZ. Licensed and insured. Free estimates.">
<style>{fonts}
:root{{--navy:#0a1433;--blue:#0b3fae;--blue2:#2459e6;--silver:#d5dcea;--paper:#eef2fa;--ink:#0a1433;--mute:#4a5878}}
*{{box-sizing:border-box;margin:0}}html{{overflow-x:clip;scroll-behavior:smooth}}body{{font:400 18px/1.65 'Onest',system-ui,sans-serif;color:var(--ink);background:var(--paper);overflow-x:clip;padding-bottom:84px}}
img{{display:block;max-width:100%}}a{{color:inherit}}:focus-visible{{outline:3px solid var(--blue2);outline-offset:3px}}
h1,h2,h3{{font-family:'Gilda Display',Georgia,serif;font-weight:400;line-height:1.08;text-wrap:balance}}
.top{{position:sticky;top:0;z-index:30;display:flex;justify-content:space-between;align-items:center;padding:10px max(16px,3vw);background:var(--navy);color:#fff}}.top img{{border-radius:10px}}
.top b{{font:700 15px 'Onest';letter-spacing:.14em;margin-left:12px}}.brand{{display:flex;align-items:center;text-decoration:none}}
.btn{{display:inline-flex;align-items:center;justify-content:center;min-height:52px;padding:0 28px;border-radius:8px;background:var(--blue2);color:#fff;font-weight:700;font-size:17px;text-decoration:none;border:2px solid var(--blue2);transition:transform .2s,background .2s}}.btn:hover{{transform:translateY(-2px);background:#1c47c0}}
.btn--o{{background:none;color:var(--ink);border-color:var(--ink)}}.btn--o:hover{{background:var(--ink);color:#fff}}.top .btn{{min-height:42px;padding:0 18px;font-size:15px;white-space:nowrap}}@media(max-width:600px){{.top .n{{display:none}}}}
.hero{{position:relative;background:var(--blue);color:#fff;text-align:center}}.hero__ph{{height:clamp(200px,22vw,300px);overflow:hidden;background:#050a1c}}.hero__ph img{{width:100%;height:100%;object-fit:cover;object-position:30% 40%}}
.hero__in{{max-width:900px;margin:0 auto;padding:44px 22px 130px}}.hero h1{{font-size:clamp(40px,6.4vw,84px)}}.hero p{{margin:20px auto 0;max-width:36ch;font-size:clamp(18px,2.2vw,22px);color:#dce6ff}}
.drip{{position:absolute;left:0;right:0;bottom:-1px;width:100%;height:clamp(60px,8vw,110px);display:block}}
.intro{{max-width:900px;margin:0 auto;padding:36px 22px 70px;text-align:center}}.intro h2{{font-size:clamp(28px,3.6vw,44px)}}.intro .ic{{margin:22px 0;display:flex;justify-content:center;gap:18px;flex-wrap:wrap;font-weight:600;color:var(--mute)}}.intro .ic span{{padding:8px 16px;border:1px solid #b9c5e0;border-radius:99px;background:#fff}}
.book{{padding:20px 22px 90px;text-align:center}}.book h2{{font-size:clamp(40px,7vw,88px);color:var(--blue);max-width:12ch;margin:0 auto}}.book p{{margin:18px 0 28px;font-weight:600}}.book .r{{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}}
.set{{background:#fff;padding:clamp(70px,9vw,120px) 22px}}.set__in{{max-width:760px;margin:0 auto}}.set h2{{font-size:clamp(32px,4.4vw,56px);text-align:center;margin-bottom:28px}}.set p{{color:var(--mute);margin-top:18px}}.set ul{{list-style:none;padding:0;margin:34px 0 0;display:grid;gap:0}}.set li{{padding:20px 0;border-top:1px solid #d5dcea;display:grid;grid-template-columns:48px 1fr;gap:6px 14px}}.set li span{{color:var(--blue2);font-weight:700;letter-spacing:.1em;grid-row:span 2;font-size:15px;padding-top:6px}}.set li h3{{font-size:24px}}.set li p{{margin:0}}
.work{{padding:clamp(70px,9vw,120px) max(18px,3vw);max-width:1300px;margin:0 auto}}.work h2{{font-size:clamp(34px,5vw,64px);text-align:center;margin-bottom:34px}}.grid{{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:14px}}
.card{{position:relative;aspect-ratio:3/4;border:0;padding:0;border-radius:14px;overflow:hidden;cursor:pointer;background:#050a1c}}.card img{{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:opacity .5s}}.card .b{{opacity:0}}.card[aria-pressed=true] .b{{opacity:1}}.card[aria-pressed=true] .a{{opacity:0}}
.tag{{position:absolute;left:12px;top:12px;background:#050a1ce6;color:#fff;border-radius:8px;padding:8px 12px;text-align:left;font-size:13px;display:grid}}.tag b{{font:700 16px 'Onest'}}.hint{{position:absolute;left:50%;bottom:12px;transform:translateX(-50%);background:#050a1cf0;color:#fff;border-radius:99px;padding:8px 16px;font:600 14px 'Onest';white-space:nowrap}}
.est{{background:var(--navy);color:#fff;padding:clamp(70px,9vw,120px) 22px}}.est__in{{max-width:620px;margin:0 auto;text-align:center}}.est h2{{font-size:clamp(34px,5vw,60px)}}.est>div>p{{margin:14px 0 28px;color:#c9d4f0}}
form{{display:grid;gap:14px;text-align:left}}form[hidden]{{display:none}}label{{display:grid;gap:6px;font-size:14px;font-weight:600;letter-spacing:.06em;text-transform:uppercase}}input,select{{font:400 17px 'Onest';min-height:52px;border-radius:8px;border:1px solid #6b7fb0;background:#050a1c;color:#fff;padding:0 14px;width:100%}}.hp{{position:absolute;left:-9999px}}form .btn{{cursor:pointer;margin-top:6px}}#ok{{min-height:1.4em;font-weight:600}}
footer{{padding:34px 22px;text-align:center;font-size:14px;color:var(--mute)}}footer a{{margin:0 8px;font-weight:600}}
.bar{{position:fixed;z-index:40;left:0;right:0;bottom:0;display:grid;grid-template-columns:repeat(4,1fr);background:var(--blue);color:#fff;padding-bottom:env(safe-area-inset-bottom)}}.bar a{{display:grid;justify-items:center;gap:2px;padding:10px 0 9px;font:700 12px 'Onest';letter-spacing:.1em;text-decoration:none;min-height:56px}}.bar svg{{width:24px;height:24px}}
@media(min-width:900px){{.bar{{left:50%;right:auto;transform:translateX(-50%);width:520px;bottom:16px;border-radius:14px}}}}
@media(prefers-reduced-motion:reduce){{*{{transition:none!important;scroll-behavior:auto!important}}}}
</style></head><body>
<form name="quote" data-netlify="true" netlify-honeypot="bot" hidden><input name="form-name"><input name="name"><input name="phone"><input name="job"><input name="bot"></form>
<header class="top"><a class="brand" href="#"><img src="{b64('logo-sq.jpg')}" width="44" height="44" alt="JB'S Pro Painters LLC logo"><b>JB'S PRO PAINTERS</b></a><a class="btn" href="tel:+16024730415">Call&nbsp;<span class="n">(602) 473-0415</span></a></header>
<main><section class="hero"><div class="hero__ph"><img src="{b64('owner-new.jpg')}" alt="Jonathan Bernal, owner of JB'S Pro Painters LLC, on his way to a job"></div>
<div class="hero__in"><h1>Painters you deal with directly.</h1><p>Interior and exterior painting for homes and businesses across the East Valley. Licensed, insured and owner-operated.</p></div>{drip}</section>
<section class="intro"><h2>Residential and commercial painting in Gilbert, Mesa, Chandler, Tempe, Scottsdale and Queen Creek</h2><div class="ic"><span>Licensed</span><span>Insured</span><span>Owner-operated</span></div></section>
<section class="book" id="book"><h2>Book your next painting project</h2><p>Free estimate. Call, text or send the short form.</p><div class="r"><a class="btn" href="#estimate">Get a free estimate</a><a class="btn btn--o" href="#work">See our work</a></div></section>
<section class="set" id="about"><div class="set__in"><h2>What sets JB'S apart?</h2>
<p>JB'S Pro Painters is run by its owner, Jonathan Bernal. When you call, you reach the person who will look at your job, give you the estimate and stand behind the finish.</p>
<p>Whether it is a home or a business, inside or out, the goal is the same: care and precision on every wall. Quality, precision and perfection.</p>
<ul><li><span>01</span><h3>Prep first</h3><p>Surfaces are cleaned, patched and protected before paint goes on.</p></li><li><span>02</span><h3>Your space, protected</h3><p>Floors, furniture and fixtures are covered and the job stays tidy.</p></li><li><span>03</span><h3>Straight answers</h3><p>You talk to the owner from the free estimate to the last coat.</p></li><li><span>04</span><h3>Done right</h3><p>Interior, exterior, cabinets, doors and commercial work, finished the way you pictured it.</p></li></ul></div></section>
<section class="work" id="work"><h2>Real projects. Tap to see the before.</h2><div class="grid">{cards}</div></section>
<section class="est" id="estimate"><div class="est__in"><h2>Get your free estimate</h2><div><p>Name, phone and the type of job is all we need. Jonathan will get back to you.</p></div>
<form id="f" name="quote" method="POST" data-netlify="true" netlify-honeypot="bot"><input type="hidden" name="form-name" value="quote"><label class="hp">Leave empty<input name="bot" tabindex="-1" autocomplete="off"></label>
<label>Name<input name="name" required autocomplete="name"></label><label>Phone<input name="phone" type="tel" required autocomplete="tel"></label>
<label>Type of job<select name="job"><option>Interior painting</option><option>Exterior painting</option><option>Cabinet refinishing</option><option>Doors and trim</option><option>Commercial</option><option>Not sure yet</option></select></label>
<button class="btn" type="submit">Request my free estimate</button><p id="ok" role="status"></p></form></div></section></main>
<footer>&copy; JB'S Pro Painters LLC &middot; (602) 473-0415 &middot; jbspropainters@gmail.com<br><a href="https://www.facebook.com/profile.php?id=61584288311213">Facebook</a></footer>
<nav class="bar" aria-label="Quick actions"><a href="#"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 11 12 3l9 8v10H3z"/></svg>HOME</a><a href="#estimate"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/></svg>ESTIMATE</a><a href="tel:+16024730415"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2z"/></svg>CALL</a><a href="sms:+16024730415"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 5h16v11H9l-5 4z"/></svg>TEXT</a></nav>
<script>
document.querySelectorAll('.card').forEach(c=>c.addEventListener('click',()=>{{const on=c.getAttribute('aria-pressed')!=='true';c.setAttribute('aria-pressed',on);c.querySelector('.tag b').textContent=on?'Before':'Fresh coat';c.querySelector('.hint').textContent=on?'Tap for finish':'Tap for before'}}));
const f=document.getElementById('f'),ok=document.getElementById('ok');f.addEventListener('submit',async e=>{{e.preventDefault();if(f.bot.value)return;const b=f.querySelector('button');b.disabled=true;try{{const r=await fetch('/',{{method:'POST',headers:{{'Content-Type':'application/x-www-form-urlencoded'}},body:new URLSearchParams(new FormData(f)).toString()}});if(!r.ok)throw 0;ok.textContent='Thanks! Jonathan will be in touch soon.';f.reset()}}catch(_){{ok.textContent='Could not send. Please call (602) 473-0415.'}}b.disabled=false}});
</script></body></html>'''
out=pathlib.Path(__file__).resolve().parent.parent/'preview/JBS-sample-drip.html'
out.write_text(html);print(out.stat().st_size//1024,'KB')
